**Server:** build the full document yourself, with the `<head>` generated dynamically.

```js
const ReactDOMServer = require("react-dom/server");
const React = require("react");
const App = require("./App").default;

function renderHead({ title = "React App", description = "" } = {}) {
  return `
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />
    <meta name="theme-color" content="#000000" />
    <meta name="description" content="${description}" />
    <title>${title}</title>
  `;
}

function renderPage(req, res) {
  const appHtml = ReactDOMServer.renderToString(React.createElement(App));
  const pageData = { title: "Dynamic title", description: "SSR demo" }; // per request

  res.send(`<!DOCTYPE html>
<html lang="en">
  <head>${renderHead(pageData)}</head>
  <body>
    <div id="root">${appHtml}</div>
    <script src="/static/js/bundle.js"></script>
  </body>
</html>`);
}
```

Notes:

- The client-side markup must match the server markup inside `#root`. Don't add browser-only logic during the first render.
- If you need head tags managed from React components (per-route titles, meta tags), use `react-helmet-async` with a `HelmetProvider` on both server and client. On the server, collect the tags after `renderToString` and inject them into the template. Otherwise, keep generating the head string as shown.
